 ('upekzar','volcanic_rock_pass','upekzar_relic_raider','upekzar_forest_stalker','upekzar_sentry_droid'),
 ('upekzar','abandoned_stone_courts','upekzar_relic_raider','upekzar_sentry_droid','upekzar_sentry_droid'),
